const snapshot = $('Normalize Sensor Payload').first().json;
const configRows = $('Read SystemConfig').all().map((i) => i.json);
const eventRows = $('Read Event History').all().map((i) => i.json);
const cfg = {};
for (const row of configRows) {
if (row.Key !== undefined && row.Key !== null && String(row.Key).trim() !== '') {
cfg[String(row.Key).trim()] = row.Value;
}
}
const lastWatered = cfg['last_watered_utc'] || '';
let elapsedHours = null;
if (lastWatered) {
const t = Date.parse(lastWatered);
if (!isNaN(t)) {
elapsedHours = Math.round(((Date.now() - t) / 3600000) * 10) / 10;
}
}
const lastAlert = cfg['last_tank_empty_alert_sent'] || '';
let alertAllowed = true;
if (lastAlert) {
const t = Date.parse(lastAlert);
if (!isNaN(t) && Date.now() - t < 12 * 3600 * 1000) {
alertAllowed = false;
}
}
const dryRun = String(cfg['dry_run_mode'] || 'false').toLowerCase() === 'true';
const historyCompact = eventRows.slice(-10).map((r) => ({
timestamp: r.Timestamp,
event_type: r.EventType,
moisture_percent: r.MoisturePercent,
weight_grams: r.WeightGrams,
soil_temp_c: r.SoilTempC,
water_temp_c: r.WaterTempC,
watered: r.WateringTriggered,
water_duration_seconds: r.WaterDurationSeconds,
heater_used: r.HeaterUsed,
species_guess: r.SpeciesGuess,
anomaly_detected: r.AnomalyDetected,
}));
const speciesGuess = cfg['last_species_guess'] || 'unknown';
const speciesConfidence = cfg['species_confidence'] || '0';
const prevTolerance = cfg['current_temp_tolerance_c'] || 'none';
const lines = [
'CURRENT EVENT: ' + snapshot.event_type + ' at ' + snapshot.captured_at_utc + '; event_id ' + snapshot.event_id,
'LIVE SENSOR SNAPSHOT (informational only â never decide on this alone):',
'  moisture_percent=' + snapshot.moisture_percent + ', weight_grams=' + snapshot.weight_grams + ', air_temp_c=' + snapshot.air_temp_c + ', air_humidity_percent=' + snapshot.air_humidity_percent + ', soil_temp_c=' + snapshot.soil_temp_c + ', water_temp_c=' + snapshot.water_temp_c + ', light_level=' + snapshot.light_level + ', tank_empty=' + snapshot.tank_empty,
'HISTORY â last 10 events (chronological):',
JSON.stringify(historyCompact, null, 2),
'LAST WATERED: ' + (lastWatered || 'never') + (elapsedHours !== null ? ' (' + elapsedHours + ' hours ago)' : ' (unknown)'),
'SPECIES: ' + speciesGuess + ' (confidence ' + speciesConfidence + ')',
'PREVIOUS TOLERANCE USED: ' + prevTolerance,
'DRY RUN MODE: ' + dryRun,
'Return strict JSON with fields: needs_watering (bool), water_duration_seconds (number, 0 if not watering), heater_on (bool), temperature_tolerance_c (number, only when heater_on or comparing), water_warmer_than_soil_action ("proceed"|"defer"), species_guess (string), species_confidence (0-1), anomaly_detected (bool), anomaly_description (string|null), ai_notes (string, the Telegram summary wording), reasoning_summary (string that EXPLICITLY cites the history trend, time since last watering, and species you relied on).',
];
return [{
json: {
context_text: lines.join('\n'),
event_id: snapshot.event_id,
event_type: snapshot.event_type,
captured_at_utc: snapshot.captured_at_utc,
tank_empty: snapshot.tank_empty,
moisture_percent: snapshot.moisture_percent,
