const storedConf = Number(dec.species_stored_confidence ?? 0);
if (newConf > storedConf) {
updates.push({ key: 'last_species_guess', value: dec.species_guess, LastUpdated: nowIso });
updates.push({ key: 'species_confidence', value: String(newConf), LastUpdated: nowIso });
}
if (dec.temperature_tolerance_c !== undefined && dec.temperature_tolerance_c !== null) {
